const payload = $json.body || $json;

const template = payload.template || 'notification';
const recipient = payload.recipient || {};
const data = payload.data || {};
const calendar = data.calendar || null;

const LOGO_URL = 'https://couponbook.vercel.app/img/logo.a3225aed.png';

const brand = {
  orange: '#f2542d',
  orangeHover: '#f76a43',
  slate: '#38424c',
  bg: '#EDF1F5',
  surface: '#FFFFFF',
  muted: '#4B5563',
  text: '#1F2933',
  border: '#D7DEE8',
  success: '#22946e',
  danger: '#9c2121',
  warning: '#a87a2a',
};

const escapeHtml = (value = '') =>
  String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');

const formatDate = (value) => {
  if (!value) return '';
  return new Date(value).toLocaleString('en-US', {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  });
};

const formatMoney = (amountCents = 0, currency = 'usd') =>
  new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: String(currency || 'usd').toUpperCase(),
  }).format(Number(amountCents || 0) / 100);

const button = (href, label, variant = 'primary') => {
  if (!href) return '';
  const bg = variant === 'secondary' ? brand.slate : brand.orange;
  return `\n    <a href="${escapeHtml(href)}" style="display:inline-block;background:${bg};color:#ffffff;text-decoration:none;font-weight:600;border-radius:999px;padding:12px 18px;margin:8px 8px 0 0;">\n      ${escapeHtml(label)}\n    </a>\n  `;
};

const detailRow = (label, value) => {
  if (!value) return '';
  return `\n    <tr>\n      <td style="padding:8px 0;color:${brand.muted};font-size:14px;width:92px;">${escapeHtml(label)}</td>\n      <td style="padding:8px 0;color:${brand.text};font-size:14px;font-weight:600;">${escapeHtml(value)}</td>\n    </tr>\n  `;
};

let subject = 'VivaSpot Notification';
let eyebrow = 'VivaSpot';
let title = 'You have a new notification';
let intro = `Hi ${escapeHtml(recipient.name || 'there')},`;
let plainMessage = 'You have a new VivaSpot notification.';
let body = `<p style="margin:0;color:#394452;line-height:1.6;">${plainMessage}</p>`;
let accentColor = brand.orange;

if (template === 'event_rsvp_confirmation') {
  const eventName = data.event?.name || 'your event';
  subject = `You're confirmed for ${eventName}`;
  eyebrow = 'RSVP Confirmed';
  title = "You're in!";
  accentColor = brand.success;
  plainMessage = `Your RSVP is confirmed for ${eventName}.`;

  body = `\n    <p style="margin:0 0 18px;color:#394452;line-height:1.6;">\n      Your RSVP is confirmed for <strong style="color:${brand.text};">${escapeHtml(eventName)}</strong>.\n    </p>\n\n    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:18px 0;padding:0;">\n      ${detailRow('When', formatDate(data.event?.startDatetime))}\n      ${detailRow('Where', data.event?.location)}\n      ${detailRow('Tickets', data.order?.quantity || 1)}\n      ${detailRow('Total', data.order?.amountCents ? formatMoney(data.order.amountCents, data.order.currency) : '')}\n    </table>\n\n    <div style="margin-top:22px;">\n      ${button(data.eventUrl, 'View Event')}\n      ${button(data.cancellationUrl, 'Cancel RSVP', 'secondary')}\n    </div>\n  `;
}

if (template === 'event_rsvp_cancelled') {
  const eventName = data.event?.name || 'your event';
  subject = `RSVP cancelled for ${eventName}`;
  eyebrow = 'RSVP Cancelled';
  title = 'Your RSVP was cancelled';
  accentColor = brand.danger;
  plainMessage = `Your RSVP for ${eventName} has been cancelled.`;

  const refundCopy = data.refund
    ? `Refund status: ${data.refund.status}. Amount: ${formatMoney(data.refund.amountCents, data.order?.currency || 'usd')}.`
    : data.refundQuote?.amountCents === 0
      ? 'No refund was issued under the event refund policy.'
      : '';

  body = `\n    <p style="margin:0 0 18px;color:#394452;line-height:1.6;">\n      Your RSVP for <strong style="color:${brand.text};">${escapeHtml(eventName)}</strong> has been cancelled.\n    </p>\n\n    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:18px 0;padding:0;">\n      ${detailRow('When', formatDate(data.event?.startDatetime))}\n      ${detailRow('Where', data.event?.location)}\n      ${detailRow('Refund', refundCopy)}\n    </table>\n  `;
}

if (template === 'subscription_renewal_reminder') {
  subject = `Your VivaSpot subscription renews on ${data.renewalDate || 'soon'}`;
  eyebrow = 'Renewal Reminder';
  title = 'Your subscription renews soon';
  accentColor = brand.orange;
  plainMessage = `Your VivaSpot subscription will automatically renew on ${data.renewalDate || 'your upcoming renewal date'}.`;

  body = `\n    <p style="margin:0 0 18px;color:#394452;line-height:1.6;">\n      Your VivaSpot subscription will automatically renew on <strong style="color:${brand.text};">${escapeHtml(data.renewalDate || 'your upcoming renewal date')}</strong>.\n    </p>\n    <div style="margin-top:22px;">\n      ${button(data.profileUrl, 'Manage Subscription')}\n    </div>\n  `;
}

if (template === 'subscription_cancellation_confirmation') {
  subject = 'Your VivaSpot subscription has been cancelled';
  eyebrow = 'Subscription Cancelled';
  title = 'Your subscription was cancelled';
  accentColor = brand.warning;
  plainMessage = `Your VivaSpot subscription has been cancelled. You will keep access until ${data.accessUntil || 'the end of your current period'}.`;

  body = `\n    <p style="margin:0 0 18px;color:#394452;line-height:1.6;">\n      Your VivaSpot subscription has been cancelled. You will keep access until\n      <strong style="color:${brand.text};">${escapeHtml(data.accessUntil || 'the end of your current period')}</strong>.\n    </p>\n    <div style="margin-top:22px;">\n      ${button(data.profileUrl, 'View Profile')}\n    </div>\n  `;
}

if (template === 'subscription_payment_failed') {
  subject = 'Action required: VivaSpot payment failed';
  eyebrow = 'Payment Failed';
  title = 'Please update your payment method';
  accentColor = brand.danger;
  plainMessage = 'We could not process your VivaSpot subscription payment. Please update your payment method to avoid interruption.';

  body = `\n    <p style="margin:0 0 18px;color:#394452;line-height:1.6;">\n      We could not process your VivaSpot subscription payment. Please update your payment method to avoid interruption.\n    </p>\n    <div style="margin-top:22px;">\n      ${button(data.profileUrl, 'Update Payment Method')}\n    </div>\n  `;
}

if (template === 'gift_access_notification') {
  const gifterName = data.gifterName || 'Someone';
  subject = `${gifterName} sent you VivaSpot access`;
  eyebrow = 'Gift Access';
  title = 'You received a VivaSpot gift';
  accentColor = brand.success;
  plainMessage = `${gifterName} gifted you VivaSpot access. Your membership is active and ready to use.`;

  body = `\n    <p style="margin:0 0 18px;color:#394452;line-height:1.6;">\n      <strong style="color:${brand.text};">${escapeHtml(gifterName)}</strong> gifted you VivaSpot access. Your membership is active and ready to use.\n    </p>\n    <div style="margin-top:22px;">\n      ${button(data.profileUrl, 'Open VivaSpot')}\n    </div>\n  `;
}

const html = `\n  <div style="margin:0;padding:0;background:${brand.bg};font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue',Arial,sans-serif;color:${brand.text};">\n    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${brand.bg};padding:32px 16px;">\n      <tr>\n        <td align="center">\n          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;background:${brand.surface};border-radius:16px;overflow:hidden;box-shadow:0 4px 20px rgba(0,0,0,0.10);">\n            <tr>\n              <td align="center" style="background:${brand.surface};padding:24px 28px;border-bottom:1px solid ${brand.border};">\n                <img src="${LOGO_URL}" alt="VivaSpot" width="140" style="display:block;border:0;outline:none;text-decoration:none;height:auto;max-width:140px;" />\n              </td>\n            </tr>\n\n            <tr>\n              <td style="padding:32px 28px 28px;">\n                <div style="display:inline-block;background:${accentColor};color:#ffffff;border-radius:999px;padding:6px 12px;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.04em;margin-bottom:18px;">\n                  ${escapeHtml(eyebrow)}\n                </div>\n\n                <h1 style="margin:0 0 12px;font-size:28px;line-height:1.2;color:${brand.text};font-weight:700;">\n                  ${escapeHtml(title)}\n                </h1>\n\n                <p style="margin:0 0 18px;color:${brand.text};font-size:16px;line-height:1.5;">\n                  ${intro}\n                </p>\n\n                <div style="background:#F7F9FC;border:1px solid ${brand.border};border-radius:12px;padding:20px;margin-top:18px;">\n                  ${body}\n                </div>\n              </td>\n            </tr>\n\n            <tr>\n              <td style="padding:20px 28px;background:#F7F9FC;color:${brand.muted};font-size:12px;line-height:1.5;">\n                You received this email because of activity on VivaSpot.\n                <br />\n                Template: ${escapeHtml(template)}\n              </td>\n            </tr>\n          </table>\n        </td>\n      </tr>\n    </table>\n  </div>\n`;

return [{
  json: {
    template,
    eventType: payload.eventType,
    to: recipient.email,
    recipientName: recipient.name,
    fromEmail: 'support@ivalu8.com',
    fromName: 'VivaSpot',
    subject,
    html,
    text: `${subject}\n\n${recipient.name ? `Hi ${recipient.name},\n\n` : ''}${plainMessage}`,
    calendar,
    hasCalendar: Boolean(calendar?.icsBase64),
    payload,
  }
}];

const m = $json;

const rand = () => `${Date.now().toString(36)}_${Math.random().toString(36).slice(2)}`;
const boundaryMixed = `mixed_${rand()}`;
const boundaryAlt = `alt_${rand()}`;

const encodeHeader = (s) => `=?UTF-8?B?${Buffer.from(String(s), 'utf8').toString('base64')}?=`;
const b64Wrap = (b64) => b64.match(/.{1,76}/g).join('\r\n');

const headers = [
  `From: ${m.fromName ? `${encodeHeader(m.fromName)} <${m.fromEmail}>` : m.fromEmail}`,
  `To: ${m.to}`,
  `Subject: ${encodeHeader(m.subject)}`,
  `MIME-Version: 1.0`,
  `Content-Type: multipart/mixed; boundary="${boundaryMixed}"`,
].join('\r\n');

const altPart = [
  `--${boundaryMixed}`,
  `Content-Type: multipart/alternative; boundary="${boundaryAlt}"`, '',
  `--${boundaryAlt}`,
  `Content-Type: text/plain; charset=UTF-8`,
  `Content-Transfer-Encoding: 7bit`, '',
  m.text || '', '',
  `--${boundaryAlt}`,
  `Content-Type: text/html; charset=UTF-8`,
  `Content-Transfer-Encoding: 7bit`, '',
  m.html, '',
  `--${boundaryAlt}--`, '',
].join('\r\n');

let attachmentPart = '';
if (m.hasCalendar && m.calendar?.icsBase64) {
  const method = (m.calendar.method || 'REQUEST').toUpperCase();
  const filename = m.calendar.filename || 'invite.ics';
  attachmentPart = [
    '',
    `--${boundaryMixed}`,
    `Content-Type: text/calendar; charset=UTF-8; method=${method}; name="${filename}"`,
    `Content-Transfer-Encoding: base64`,
    `Content-Disposition: attachment; filename="${filename}"`, '',
    b64Wrap(m.calendar.icsBase64), '',
  ].join('\r\n');
}

const raw = `${headers}\r\n\r\n${altPart}${attachmentPart}--${boundaryMixed}--\r\n`;
const rawBase64 = Buffer.from(raw, 'utf8').toString('base64');

return [{ json: { rawBase64, to: m.to, fromEmail: m.fromEmail, subject: m.subject } }];
